// Smooth the fixed 20 ms physics samples for drawing only. Interactions,
// timetables, speed and collision decisions keep the original engine state.
export function renderPosition203(train,state,timing=globalThis.window?.metroTiming170){const pending=timing?.pendingSeconds;if(!state.running||train.wait>0||!Number.isFinite(pending)||pending<0||pending>=.020001)return train.position;let delta=(train.speed||0)*(train.direction||1)*pending;const stop=state.engine.lines?.[train.line]?.distances?.[train.target],remaining=(stop-train.position)*(train.direction||1);if(Number.isFinite(remaining)&&remaining>=0)delta=(train.direction||1)*Math.min(Math.abs(delta),remaining);return train.position+delta;}
export function cameraShift203(view,state){const id=view.passenger178?.ride200?.trainId||state.selectedTrain,t=state.engine.trains.find(t=>t.id===id);return t&&(view.passenger178?.ride200?.trainId||['train','car','driver','cab-platform'].includes(view.cameraMode))?renderPosition203(t,state)-t.position:0;}
